(function(){
  var form=document.querySelector("form");
  if(!form) return "NO_FORM";
  var fields=Array.from(form.querySelectorAll("input,textarea,select")).map(function(e){return {tag:e.tagName,type:e.type,name:e.name,val:(e.value||"").slice(0,40)}});
  return JSON.stringify({action:form.action,method:form.method,fields:fields});
})()
